import { mk, prep, hash, rng, type Shape } from "./gen";
import { app, $, cl, RM, setTitle, say } from "./dom";
import { mount, stop, view } from "./stage";
import { ui, live } from "./game";
import { TODAY } from "./store";
import { home } from "./home";

interface Shot {
  x: number;
  y: number;
  pts: number;
}
/** Wind and gravity accumulate over flight time; more power reduces both. */
export function landing(x: number, y: number, power: number, wind: number) {
  const time = 1.25 - cl(power, 0, 1) * 0.7;
  return { x: x + wind * 28 * time ** 2, y: y + 58 * time ** 2, time };
}
export function startArchery() {
  stop();
  live(null);
  ui.ph = "archery";
  setTitle("Poise Archery");
  app.className = "archery-screen";
  app.innerHTML = `<header class="site-header"><button class="brand-home" id="arch-home">Pinpoise</button><span class="edition">Practice range</span></header>
  <div class="arch-intro"><h1>Poise Archery</h1><p>Read the wind. Find the balance.</p></div>
  <div class="arch-hud"><span id="arch-round"></span><span id="arch-wind"></span><b id="arch-total">0 pts</b></div>
  <div id="stage" class="arch-range"><canvas id="cv" tabindex="0" role="img" aria-label="Archery range. Drag back and release to shoot. Arrow keys aim; Space shoots." aria-describedby="arch-help"></canvas></div>
  <div class="arch-controls"><label for="arch-power">Power <output id="arch-power-value">70%</output></label><input id="arch-power" type="range" min="25" max="100" value="70">
  <p class="small mute" id="arch-help">Pull back anywhere in the range, then release.<br>More power means less drift and drop. Arrow keys aim; Space shoots.</p>
  <p id="arch-status" role="status">Three shots per shape. Aim for its balance point.</p><div class="arch-actions"><button class="btn" id="arch-fire">Shoot pin</button><button class="btn ghost" id="arch-next" hidden>Next shape</button></div><button class="arch-restart" id="arch-restart">Start over</button></div>`;
  app.scrollTop = 0;
  const random = rng(hash(`archery:${TODAY}`));
  const shapes = ["hammer", "spoon", "star"].map((fam, i) => {
    const raw = mk(`archery:${TODAY}`, i, fam);
    raw.rot = (i - 1) * 0.22;
    return prep(raw);
  });
  let round = 0,
    shots: Shot[] = [],
    total = 0,
    wind = 0,
    aim = { x: 300, y: 205 },
    power = 0.7,
    done = false;
  let flight: {
    start: number;
    end: ReturnType<typeof landing>;
    aim: typeof aim;
  } | null = null;
  let drag: { id: number; x: number; y: number; aim: typeof aim } | null = null;
  const cv = $<HTMLCanvasElement>("#cv"),
    fire = $<HTMLButtonElement>("#arch-fire"),
    next = $<HTMLButtonElement>("#arch-next"),
    slider = $<HTMLInputElement>("#arch-power"),
    status = $("#arch-status");
  const descriptions = [
    "Hammer: a wide head above a narrow handle, tilted slightly left.",
    "Spoon: a rounded bowl above a long narrow handle.",
    "Star: five points around a broad center, tilted slightly right.",
  ];
  const windWords = () =>
    `Wind ${Math.abs(wind).toFixed(1)} meters per second to the ${wind < 0 ? "left" : "right"}.`;
  function describeAim() {
    return `Aim ${Math.round(aim.x / 6)} percent from the left, ${Math.round(aim.y / 6)} percent from the top. Power ${Math.round(power * 100)} percent. ${windWords()}`;
  }
  function update() {
    const materials = [
      ...new Set(shapes[round].parts.map((p) => String(p[0]))),
    ].join(", ");
    cv.setAttribute(
      "aria-label",
      `Archery range. ${descriptions[round]} Materials: ${materials}. ${describeAim()} Arrow keys aim; Space shoots.`,
    );
    $("#arch-round").textContent =
      `Shape ${round + 1} / 3 · Shot ${Math.min(shots.length + 1, 3)} / 3`;
    $("#arch-wind").textContent =
      `${wind < 0 ? "←" : "→"} Wind ${Math.abs(wind).toFixed(1)} m/s`;
    $("#arch-total").textContent = `${total} pts`;
    fire.disabled = slider.disabled = !!flight || shots.length >= 3 || done;
  }
  function newWind() {
    wind = Math.round((random() * 6 - 3) * 10) / 10;
    update();
  }
  function shoot() {
    if (flight || shots.length >= 3 || done) return;
    flight = {
      start: performance.now(),
      end: landing(aim.x, aim.y, power, wind),
      aim: { ...aim },
    };
    status.textContent = "Pin in flight…";
    update();
  }
  function finish() {
    if (!flight) return;
    const { x, y } = flight.end,
      shape = shapes[round],
      u = (x - 110) / 380,
      v = (y - 20) / 380;
    const hit = onShape(shape, u, v),
      distance = Math.hypot((u - shape.c[0]) * 380, (v - shape.c[1]) * 380);
    const pts = hit
      ? Math.round(
          100 * Math.exp(-Math.pow(Math.max(0, distance - 16) / 85, 1.35)),
        )
      : 0;
    shots.push({ x, y, pts });
    total += pts;
    flight = null;
    status.textContent = hit
      ? `${pts === 100 ? "Perfect balance!" : "Pin landed!"} +${pts} points.`
      : "Missed the shape. Adjust your aim for the wind and drop.";
    if (shots.length === 3) {
      next.hidden = false;
      fire.hidden = true;
      next.textContent = round === 2 ? "See result" : "Next shape";
      status.textContent += " The ring shows the balance point.";
      next.focus();
    } else {
      newWind();
      status.textContent += ` ${windWords()}`;
    }
    update();
    say(status.textContent || "");
  }
  function point(e: PointerEvent) {
    const r = $("#stage").getBoundingClientRect(),
      s = Math.min(r.width / 600, r.height / 600);
    return {
      x: (e.clientX - r.left - (r.width - s * 600) / 2) / s,
      y: (e.clientY - r.top - (r.height - s * 600) / 2) / s,
    };
  }
  cv.onpointerdown = (e) => {
    if (
      flight ||
      shots.length >= 3 ||
      done ||
      (e.pointerType === "mouse" && e.button !== 0)
    )
      return;
    const r = $("#stage").getBoundingClientRect();
    if (
      e.clientY < r.top ||
      e.clientY > r.bottom ||
      e.clientX < r.left ||
      e.clientX > r.right
    )
      return;
    cv.focus({ preventScroll: true });
    drag = { id: e.pointerId, ...point(e), aim: { ...aim } };
    cv.setPointerCapture(e.pointerId);
  };
  cv.onpointermove = (e) => {
    if (!drag || drag.id !== e.pointerId) return;
    const p = point(e);
    aim = {
      x: cl(drag.aim.x + (drag.x - p.x) * 1.6, 20, 580),
      y: cl(drag.aim.y + (drag.y - p.y) * 1.6, -70, 420),
    };
  };
  cv.onpointerup = (e) => {
    if (!drag || drag.id !== e.pointerId) return;
    const p = point(e),
      moved = Math.hypot(p.x - drag.x, p.y - drag.y);
    drag = null;
    if (cv.hasPointerCapture(e.pointerId))
      cv.releasePointerCapture(e.pointerId);
    if (moved > 8) shoot();
  };
  cv.onpointercancel = cv.onlostpointercapture = () => {
    drag = null;
  };
  cv.onkeydown = (e) => {
    if (flight || done || shots.length >= 3) return;
    const d = e.shiftKey ? 12 : 4;
    if (
      [
        "ArrowLeft",
        "ArrowRight",
        "ArrowUp",
        "ArrowDown",
        " ",
        "Enter",
      ].includes(e.key)
    )
      e.preventDefault();
    if (e.key === "ArrowLeft") aim.x -= d;
    if (e.key === "ArrowRight") aim.x += d;
    if (e.key === "ArrowUp") aim.y -= d;
    if (e.key === "ArrowDown") aim.y += d;
    aim.x = cl(aim.x, 20, 580);
    aim.y = cl(aim.y, -70, 420);
    if (e.key.startsWith("Arrow")) {
      update();
      say(describeAim());
    }
    if (e.key === " " || e.key === "Enter") shoot();
  };
  slider.oninput = () => {
    power = +slider.value / 100;
    $("#arch-power-value").textContent = `${slider.value}%`;
    update();
  };
  fire.onclick = shoot;
  $("#arch-home").onclick = () => {
    stop();
    home();
  };
  $("#arch-restart").onclick = startArchery;
  next.onclick = () => {
    if (round === 2) {
      done = true;
      next.textContent = "Play again";
      next.onclick = startArchery;
      status.textContent = `${total} / 900 points. ${total >= 650 ? "A steady hand." : "Every shot teaches you the wind."}`;
      $("#arch-round").textContent = "Range complete · 9 shots";
      say(status.textContent);
      return;
    }
    round++;
    shots = [];
    aim = { x: 300, y: 205 };
    next.hidden = true;
    fire.hidden = false;
    status.textContent = "New shape. Three fresh shots.";
    newWind();
    status.textContent += ` ${descriptions[round]} ${windWords()}`;
    cv.focus({ preventScroll: true });
  };
  newWind();
  mount((t) => {
    const x = view.cx,
      f = view.f,
      scale = Math.min(f.w / 600, f.h / 600),
      shape = shapes[round];
    x.save();
    x.translate(f.x + (f.w - 600 * scale) / 2, f.y + (f.h - 600 * scale) / 2);
    x.scale(scale, scale);
    x.strokeStyle = view.ink;
    x.fillStyle = view.ink;
    x.drawImage(shape.sp, 110, 20, 380, 380);
    if (!RM) {
      x.globalAlpha = 0.18;
      x.lineWidth = 1.5;
      for (let i = 0; i < 7; i++) {
        const px = (((i * 97 + t * wind * 0.025) % 600) + 600) % 600,
          py = 55 + i * 57;
        x.beginPath();
        x.moveTo(px, py);
        x.lineTo(px + Math.sign(wind) * (12 + Math.abs(wind) * 7), py);
        x.stroke();
      }
      x.globalAlpha = 1;
    }
    if (shots.length >= 3) {
      x.beginPath();
      x.arc(110 + shape.c[0] * 380, 20 + shape.c[1] * 380, 16, 0, Math.PI * 2);
      x.lineWidth = 7;
      x.strokeStyle = view.bg;
      x.stroke();
      x.lineWidth = 2;
      x.strokeStyle = view.ink;
      x.stroke();
    }
    for (const s of shots) drawPin(x, s.x, s.y, view.ink, view.bg, 6);
    if (!flight && shots.length < 3 && !done) {
      x.globalAlpha = 0.55;
      x.lineWidth = 1.5;
      x.setLineDash([4, 7]);
      x.beginPath();
      x.moveTo(300, 530);
      x.lineTo(aim.x, aim.y);
      x.stroke();
      x.setLineDash([]);
      x.globalAlpha = 1;
      x.beginPath();
      x.arc(aim.x, aim.y, 11, 0, Math.PI * 2);
      x.stroke();
      x.beginPath();
      x.moveTo(aim.x - 17, aim.y);
      x.lineTo(aim.x + 17, aim.y);
      x.moveTo(aim.x, aim.y - 17);
      x.lineTo(aim.x, aim.y + 17);
      x.stroke();
    }
    const pull = drag ? 20 : 0;
    x.lineWidth = 3;
    x.beginPath();
    x.moveTo(255, 525);
    x.quadraticCurveTo(300, 475, 345, 525);
    x.stroke();
    x.lineWidth = 1.5;
    x.beginPath();
    x.moveTo(255, 525);
    x.lineTo(300, 540 + pull);
    x.lineTo(345, 525);
    x.stroke();
    if (flight) {
      const u = RM ? 1 : cl((t - flight.start) / (flight.end.time * 800), 0, 1);
      drawPin(
        x,
        300 + (flight.aim.x - 300) * u + (flight.end.x - flight.aim.x) * u * u,
        530 + (flight.aim.y - 530) * u + (flight.end.y - flight.aim.y) * u * u,
        view.ink,
        view.bg,
        4 + u * 2,
      );
      if (u === 1) finish();
    } else if (shots.length < 3 && !done)
      drawPin(x, 300, 532 + pull, view.ink, view.bg, 6);
    x.restore();
  }, true);
}
function onShape(shape: Shape, u: number, v: number) {
  if (u < 0 || v < 0 || u >= 1 || v >= 1) return false;
  const x = Math.floor(u * shape.sp.width),
    y = Math.floor(v * shape.sp.height),
    left = Math.max(0, x - 5),
    top = Math.max(0, y - 5);
  const data = shape.sp
    .getContext("2d")!
    .getImageData(
      left,
      top,
      Math.min(11, shape.sp.width - left),
      Math.min(11, shape.sp.height - top),
    ).data;
  for (let i = 3; i < data.length; i += 4) if (data[i] > 100) return true;
  return false;
}
function drawPin(
  x: CanvasRenderingContext2D,
  px: number,
  py: number,
  ink: string,
  bg: string,
  r: number,
) {
  x.strokeStyle = bg;
  x.lineWidth = 5;
  x.beginPath();
  x.moveTo(px, py);
  x.lineTo(px + 8, py - 22);
  x.stroke();
  x.strokeStyle = ink;
  x.lineWidth = 2;
  x.stroke();
  x.beginPath();
  x.arc(px + 8, py - 22, r, 0, Math.PI * 2);
  x.fillStyle = ink;
  x.fill();
  x.strokeStyle = bg;
  x.lineWidth = 2;
  x.stroke();
  x.strokeStyle = ink;
}
